<?php get_header(); while (have_posts()) : the_post(); $id = get_the_ID(); $artist = absint(ag_meta('artist_id')); $sources = ag_source_links($id); $sourced = ag_meta('meaning_type') === 'sourced' && $sources && ag_meta('artist_comment'); $has_spotify_player = function_exists('ag_spotify_embed_url') && ag_spotify_embed_url($id); ?>
<main id="main" class="shell profile-main song-profile"><a class="back-link" href="<?php echo esc_url(ag_url('songs')); ?>">← All songs</a><div class="profile-layout"><div class="profile-art-column">
<?php if ($has_spotify_player) : ?>
<?php ag_spotify_player($id); ?>
<?php else : ?>
<?php ag_art($id, 'profile-art', true); ?><p class="art-credit"><?php echo esc_html(ag_meta('artwork_credit') ?: 'Original abstract artwork · Not official cover art'); ?></p><div class="listen-panel"><p class="eyebrow">A LITTLE CLOSER TO THE MUSIC</p><h2>Make room for a listen.</h2><?php ag_listen($id); ?></div>
<?php endif; ?>
</div><div class="profile-copy"><p class="eyebrow">BETWEEN THE NOTES / SONG EXPLORER</p><div class="profile-title"><h1><?php the_title(); ?></h1><?php ag_save_button($id, 'large-save'); ?></div><?php if ($artist && get_post_status($artist) === 'publish') : ?><a class="artist-byline" href="<?php echo esc_url(get_permalink($artist)); ?>">by <?php echo esc_html(get_the_title($artist)); ?> <?php echo ag_icon('diagonal'); ?></a><?php endif; ?><div class="tag-list"><?php foreach (['genre', 'mood'] as $tax) { $terms = get_the_terms($id, $tax); foreach ($terms && !is_wp_error($terms) ? $terms : [] as $term) { echo '<a class="tag" href="' . esc_url(ag_url('songs') . '?filter_' . $tax . '=' . $term->slug) . '">' . esc_html($term->name) . '</a>'; } } ?></div><p class="profile-intro"><?php echo esc_html(get_the_excerpt()); ?></p><?php ag_demo_notice($id); ?>
<div class="meaning-label"><?php echo ag_icon('spark'); ?> Afterglow interpretation</div><p class="fine-print">An independent interpretation, not a statement of the artist’s intent.</p><div class="prose"><?php the_content(); ?></div>
<?php if (ag_meta('credits')) : ?><p class="fine-print"><strong>Recording artists:</strong> <?php echo esc_html(ag_meta('credits')); ?></p><?php endif; ?>
<?php if (ag_meta('themes')) : ?><div class="theme-note"><strong>Themes we’re exploring</strong><p><?php echo esc_html(ag_meta('themes')); ?></p></div><?php endif; ?>
<section class="profile-section"><p class="eyebrow">KEEPING THE STORY HONEST</p><h2>In the artist’s own words.</h2><?php if ($sourced) : ?><p class="attribution-label">Artist statement · editorial paraphrase, not a direct quotation</p><p><?php echo esc_html(ag_meta('artist_comment')); ?></p><?php else : ?><p>No verified artist explanation has been added to this page. The notes above are editorial, and should not be read as the artist’s confirmed meaning.</p><?php endif; ?><?php if ($sources) : ?><h3>Sources & further reading</h3><ul class="source-list"><?php foreach ($sources as $link) { echo '<li><a href="' . esc_url($link[1]) . '" target="_blank" rel="noopener noreferrer">' . esc_html($link[0]) . ' ↗</a></li>'; } ?></ul><?php endif; ?><?php if (ag_meta('release') && $sources) : ?><p class="fine-print">Release date: <?php echo esc_html(ag_meta('release')); ?> · See sources above.</p><?php endif; ?></section></div></div>
<?php $related = ag_related_ids($id); if ($related) : ?><section class="section related-section"><?php ag_section_heading('STAY WITH THE FEELING', 'Your next song starts here.'); ?><div class="related-grid"><?php foreach ($related as $other) { ag_card($other); } ?></div></section><?php endif; ?>
</main><?php endwhile; get_footer(); ?>
